import {t,language,setLanguage,esc,word,hex,fmt,buyData} from './ui.mjs';
import {mountStudio} from './studio.mjs?v=51';
const $=s=>document.querySelector(s), app=$('#app');
let config,account=null,provider,chain=null,balances=null,busy=false,quantity=1,lastTx=null,loadError=false,readId=0;
let projectConfigs;
const currentProject=()=>route().includes('fillout')?'fillout':'openbook';
const projectName=k=>k==='fillout'?'FillOut':'OpenBook';
const projectStats={};
async function readProject(k){const c=projectConfigs[k];const vals=await Promise.all(['0x5df0df80','0x4facfe37','0xbdf7f54e','0xb10b69cc'].map(s=>call(c.partsAddress,s)));const stats={caps:vals.slice(0,2).map(BigInt),minted:vals.slice(2).map(BigInt)};projectStats[k]=stats;return stats;}

const names=['Quote','Settle'];
const short=a=>a.slice(0,6)+'…'+a.slice(-4);
const route=()=>location.hash.slice(1)||'projects';
function toast(en,zh){$('#toast').textContent=t(en,zh);$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',7000);}
function header(){document.documentElement.lang=language==='zh'?'zh-CN':'en';document.querySelector('header').innerHTML=`<a class="brand" href="#projects"><span class="brand-mark">F</span>FillOut</a><nav>${[['studio','Studio','工作室'],['projects','Projects','项目'],['market','Market','市场'],['data','Data','数据'],['wallet','My holdings','我的持仓'],['whitepaper','Whitepaper','白皮书']].map(([r,en,zh])=>`<a href="#${r}" class="${route()===r?'active':''}">${t(en,zh)}</a>`).join('')}</nav><div class="language-picker"><button data-lang="zh" class="${language==='zh'?'selected':''}">中文</button><span>/</span><button data-lang="en" class="${language==='en'?'selected':''}">EN</button></div><button id="connect">${account?short(account):t('Connect wallet','连接钱包')}</button>`;$('#connect').onclick=()=>connect().catch(error);document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{setLanguage(b.dataset.lang);render();});document.querySelector('.network-bar').innerHTML=`<span>ROBINHOOD CHAIN <b>${t("MAINNET","主网")}</b></span><span>${t('Mainnet ETH','主网 ETH')} · 4663</span>`;document.querySelector('footer').innerHTML=`<a href="#projects">FillOut</a><span>${t('Build logic. Keep the state.','构建逻辑，保存状态。')}</span><a href="#whitepaper">${t('Protocol & fees','协议与费用')}</a>`;}
function error(e){if(e?.code===4001)toast('Request cancelled in wallet.','已在钱包中取消请求。');else{const detail=String(e?.data?.message||e?.shortMessage||e?.message||'Unknown wallet or network error').replace(/^Error:\s*/,'').slice(0,180);toast('Request failed: '+detail,'请求失败：'+detail);}}
function useProvider(){if(provider)return;provider=window.ethereum;if(!provider)throw Error(t("No wallet found. Open a wallet-enabled browser.","未检测到钱包，请使用支持钱包的浏览器。"));provider.on?.('accountsChanged',a=>{account=a[0]||null;balances=null;chain=null;render();refresh();});provider.on?.('chainChanged',()=>{balances=null;chain=null;render();refresh();});}
async function connect(){useProvider();const accounts=await provider.request({method:'eth_requestAccounts'});account=accounts[0];await ensureNetwork();await refresh();}
async function ensureNetwork(){const expected=hex(config.chainId);if(Number(await provider.request({method:'eth_chainId'}))!==config.chainId){try{await provider.request({method:'wallet_switchEthereumChain',params:[{chainId:expected}]});}catch(e){if(e.code!==4902)throw e;await provider.request({method:'wallet_addEthereumChain',params:[{chainId:expected,chainName:config.chainName,rpcUrls:[config.rpcUrl],blockExplorerUrls:[config.explorerUrl],nativeCurrency:{name:'Ether',symbol:'ETH',decimals:18}}]});}if(Number(await provider.request({method:'eth_chainId'}))!==config.chainId)throw Error(t("Switch to the correct network.","请切换到正确的网络。"));}}
async function rpc(method,params){if(provider&&Number(await provider.request({method:'eth_chainId'}))===config.chainId)return provider.request({method,params});const response=await fetch(config.rpcUrl,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({jsonrpc:'2.0',id:1,method,params}),signal:AbortSignal.timeout(12000)});const json=await response.json();if(json.error)throw Error('rpc');return json.result;}
const call=(to,data)=>rpc('eth_call',[{to,data},'latest']);
async function refresh(){const config=projectConfigs[currentProject()];const id=++readId;try{const p=config.partsAddress,d=config.deskAddress;const values=await Promise.all(['0x5df0df80','0x4facfe37','0xbdf7f54e','0xb10b69cc'].map(s=>call(p,s)));const [price,owner,parts,code]=await Promise.all([call(d,'0xe73faa2d'),call(p,'0x8da5cb5b'),call(d,'0x'+config.partsSelector),rpc('eth_getCode',[d,'latest'])]);if(code==='0x'||('0x'+owner.slice(-40)).toLowerCase()!==d.toLowerCase()||('0x'+parts.slice(-40)).toLowerCase()!==p.toLowerCase())throw Error('contract');const locked=config.circuitsAddress?await Promise.all([0,1].map(i=>call(config.partsAddress,'0x00fdd58e'+config.circuitsAddress.slice(2).toLowerCase().padStart(64,'0')+word(i)).then(BigInt))):[0n,0n];const next={caps:values.slice(0,2).map(BigInt),minted:values.slice(2).map(BigInt),locked,price:BigInt(price)};let nextBalances=null;if(account){const address=account.slice(2).toLowerCase().padStart(64,'0');nextBalances=await Promise.all([0,1].map(i=>call(p,'0x00fdd58e'+address+word(i)).then(BigInt)));}if(id!==readId)return;chain=next;balances=nextBalances;loadError=false;}catch{if(id!==readId)return;loadError=true;chain=null;balances=null;}if(route()!=='studio')render();}
const badge=()=>`<span class="official">${t('Official','官方')}</span>`;
const intro=(en,zh,subEn,subZh)=>`<div class="page-heading"><div class="eyebrow">FILLOUT / OPENBOOK</div><h1>${t(en,zh)}</h1><p class="muted">${t(subEn,subZh)}</p></div>`;
const progress=i=>chain?`${(chain.caps[i]-chain.locked[i]).toLocaleString()} / ${chain.caps[i].toLocaleString()}`:'— / 50,000';
const mintCounter=i=>chain?`${chain.minted[i].toLocaleString()} ${t('minted','已铸造')} · ${progress(i)} ${t('available','可用')}`:`— ${t('minted','已铸造')} · ${progress(i)} ${t('available','可用')}`;
function projects(){app.innerHTML=intro('Projects','项目','Choose a project, then mint Quote or Settle.','选择项目，然后铸造 Quote 或 Settle。')+'<div class="project-list">'+['openbook','fillout'].map(k=>'<article class="project-row"><div><h2>'+projectName(k)+' '+badge()+'</h2><p>Quote · Settle</p><p class="muted">'+t("Robinhood Chain Mainnet","Robinhood Chain 主网")+'</p></div><div><strong id="supply-'+k+'">'+t("Loading…","加载中…")+'</strong><p>'+t("Total minted / lifetime cap","累计铸造 / 铸造上限")+'</p></div><a class="primary link-button" href="#'+k+'-0">'+t("View project ↗","查看项目 ↗")+'</a></article>').join('')+'</div>';for(const k of ['openbook','fillout']){const el=$('#supply-'+k);readProject(k).then(s=>{if(el.isConnected)el.textContent=(s.minted[0]+s.minted[1]).toLocaleString('en-US')+' / '+(s.caps[0]+s.caps[1]).toLocaleString('en-US');}).catch(()=>{if(el.isConnected)el.textContent=t("Data unavailable","数据暂不可用");});}}

function market(){app.innerHTML=intro('Market','市场','Choose a project and part to trade.','选择项目和组件进行交易。')+['openbook','fillout'].map(k=>{const c=projectConfigs[k];return '<section class="market-project-head"><div class="project-mark">'+projectName(k)[0]+'</div><div><h2>'+projectName(k)+' '+badge()+'</h2><small>'+short(c.marketAddress)+'</small></div></section><div class="asset-market-list">'+names.map((n,i)=>'<a class="asset-market-row" href="#market-'+k+'-'+i+'"><div class="asset-glyph">'+(i?'▣':'⊼')+'</div><div><h2>'+n+' '+badge()+'</h2><p>'+(i?t("Memory · one bit of state","存储器 · 一位状态"):t("NAND logic · two inputs, one output","与非逻辑 · 两个输入，一个输出"))+'</p><small>'+short(c.partsAddress)+' · '+t('Token ID','代币编号')+' '+i+'</small></div><div class="asset-stat"><strong id="market-supply-'+k+'-'+i+'">'+t("Loading…","加载中…")+'</strong><span>'+t("minted / cap","已铸造 / 上限")+'</span></div><span class="asset-arrow">'+t("Open market ↗","进入市场 ↗")+'</span></a>').join('')+'</div>';}).join('');for(const k of ['openbook','fillout'])readProject(k).then(s=>names.forEach((n,i)=>{const el=$('#market-supply-'+k+'-'+i);if(el)el.textContent=s.minted[i].toLocaleString('en-US')+' / '+s.caps[i].toLocaleString('en-US');})).catch(()=>names.forEach((n,i)=>{const el=$('#market-supply-'+k+'-'+i);if(el)el.textContent=t("Data unavailable","数据暂不可用");}));}

async function loadCircuitHoldings(){const box=$('#circuit-holdings');if(!box||!account)return;try{const count=Number(BigInt(await rpc('eth_call',[{to:config.circuitsAddress,data:'0xaaccf1ec'},'latest'])));const ids=[];for(let i=0;i<count;i++){const owner=await rpc('eth_call',[{to:config.circuitsAddress,data:'0x6352211e'+word(i)},'latest']);if(('0x'+owner.slice(-40)).toLowerCase()===account.toLowerCase())ids.push(i);}box.innerHTML=ids.length?ids.map(i=>'<article class="holding-row"><div><h2>FillOut Circuit NFT</h2><p>ERC-721 · ID '+i+'</p></div><strong class="balance-number">#'+i+'</strong><a class="link-button" href="'+config.explorerUrl+'/token/'+config.circuitsAddress+'?a='+i+'" target="_blank" rel="noopener">'+t("View NFT ↗","查看 NFT ↗")+'</a></article>').join(''):'<div class="holdings-empty">'+t('No circuit NFTs yet.','暂无电路 NFT。')+'</div>';}catch{box.innerHTML='<div class="holdings-empty">'+t('Circuit NFTs could not be loaded.','无法加载电路 NFT。')+'</div>';}}
function holdings(){app.innerHTML=intro('My holdings','我的持仓','Parts and circuit NFTs for both projects.','两个项目的组件和电路 NFT。')+(!account?'<button id="hold-connect" class="primary">'+t("Connect wallet","连接钱包")+'</button>':['openbook','fillout'].map(k=>'<section class="holdings-box"><h2>'+projectName(k)+'</h2><div id="hold-'+k+'">'+t("Loading…","加载中…")+'</div></section>').join(''));$('#hold-connect')?.addEventListener('click',()=>connect().catch(error));if(!account)return;const owner=account;for(const k of ['openbook','fillout']){const c=projectConfigs[k],box=$('#hold-'+k);(async()=>{const amounts=await Promise.all([0,1].map(i=>call(c.partsAddress,'0x00fdd58e'+owner.slice(2).padStart(64,'0')+word(i)).then(BigInt)));const count=Number(BigInt(await call(c.circuitsAddress,'0xaaccf1ec')));let ids=[];for(let start=0;start<count;start+=20){const batch=await Promise.all(Array.from({length:Math.min(20,count-start)},async(_,j)=>{const id=start+j;const result=await call(c.circuitsAddress,'0x6352211e'+word(id));return ('0x'+result.slice(-40)).toLowerCase()===owner.toLowerCase()?id:null;}));ids.push(...batch.filter(x=>x!==null));}if(!box.isConnected||account!==owner)return;box.innerHTML=amounts.map((n,i)=>'<article class="holding-row"><h3>'+names[i]+'</h3><strong>'+n.toLocaleString('en-US')+'</strong><a href="#'+k+'-'+i+'">'+t("Mint more ↗","继续铸造 ↗")+'</a></article>').join('')+'<h3>'+t("Circuit NFTs","电路 NFT")+'</h3>'+(ids.length?ids.map(id=>'<article class="holding-row"><span>'+projectName(k)+' '+t('Circuit','电路')+' #'+id+'</span><a target="_blank" rel="noopener" href="'+c.explorerUrl+'/token/'+c.circuitsAddress+'?a='+id+'">'+t("View NFT ↗","查看 NFT ↗")+'</a></article>').join(''):'<p>'+t("No circuit NFTs in this wallet.","此钱包暂无电路 NFT。")+'</p>');})().catch(()=>{if(box.isConnected)box.textContent=t("Unable to load holdings. Please retry.","无法加载持仓，请重试。");});}}

function mintPage(i,project="openbook"){const selected=projectConfigs[project];  const live=true,projectName=project==="fillout"?"FillOut":"OpenBook";const price=chain?.price||200000000000000n;app.innerHTML=intro(projectName,projectName,projectName+' · Quote / Settle',projectName+' · Quote / Settle')+`<div class="mint-layout"><section class="part-overview"><div class="part-symbol">${i===0?'⊼':'▣'}</div><h2>${names[i]} ${badge()}</h2><p>${i===0?t('Two inputs, one NAND output. Connect Quote gates to build combinational circuits.','两个输入，一个 NAND 输出。连接 Quote 门以构建组合电路。'):t('One bit of memory. Settle stores state between simulation steps.','一位存储器。Settle 在模拟步骤之间保存状态。')}</p><p>${live?mintCounter(i):t('Supply pending deployment','供应量待部署')}</p><a class="text-link" href="#studio">${t('Open in Studio','在工作室中打开')} ↗</a></section><section class="mint-panel"><div class="part-tabs">${names.map((n,j)=>`<a class="link-button ${i===j?'primary':''}" href="#${project}-${j}">${t('Mint','铸造')} ${n}</a>`).join('')}</div><h2>${t('Mint','铸造')} ${names[i]}</h2><label class="amount-label" for="quantity">${t('Quantity','数量')}</label><input id="quantity" type="number" min="1" max="50000" step="1" value="${quantity}" ${busy?'disabled':''}><div class="quantity-presets">${[1,10,100].map(q=>`<button data-quantity="${q}" ${busy?'disabled':''}>${q}</button>`).join('')}</div><div class="costs"><div><span>${t('Unit price','单价')}</span><strong>${live?fmt(price)+' ETH':t('Not announced','尚未公布')}</strong></div><div><span>${t('Parts subtotal','组件小计')}</span><strong id="subtotal">${live?fmt(price*BigInt(quantity))+' ETH':'—'}</strong></div><div><span>${t('Platform fee','平台费用')}</span><strong>${t('Estimated at mint','铸造时估算')}</strong></div></div><p class="small-note">${t('An estimated network-equivalent platform fee is added. Wallet network fees are charged separately.','另加等于预估网络费的平台费用。钱包网络费单独收取。')}</p><button id="mint" class="primary" ${busy||!live?'disabled':''}>${busy?t('Waiting for wallet…','等待钱包…'):t('Mint','铸造')+' '+names[i]}</button><p class="small-note">${t('Opens your wallet directly.','直接打开钱包。')}</p><div id="mint-status" role="status">${lastTx?txLink():''}</div></section></div>`;$('#quantity').onchange=e=>{quantity=Math.min(50000,Math.max(1,Math.floor(Number(e.target.value)||1)));e.target.value=quantity;$('#subtotal').textContent=live?fmt(price*BigInt(quantity))+' ETH':'—';};document.querySelectorAll('[data-quantity]').forEach(b=>b.onclick=()=>{quantity=Number(b.dataset.quantity);mintPage(i,project);});$('#mint').onclick=()=>{if(live)mint(i);};}
function txLink(){return `<a class="text-link" href="${config.explorerUrl}/tx/${lastTx.hash}" target="_blank" rel="noopener">${lastTx.status==='confirmed'?t('Mint confirmed','铸造已确认'):lastTx.status==='failed'?t('Transaction reverted','交易已回滚'):t('Transaction submitted · view status','交易已提交 · 查看状态')} ↗</a>`;}
async function mint(i){const config=projectConfigs[currentProject()];if(busy)return;busy=true;render();try{if(!account)await connect();else await ensureNetwork();await refresh();if(!chain)throw Error(t("Unable to read contract data. Please retry.","无法读取合约数据，请重试。"));if(config.partsAddress!==projectConfigs[currentProject()].partsAddress)throw Error(t("Project changed. Retry mint.","项目已更改，请重新铸造。"));const sender=account,q=BigInt(quantity);if(q<=0n||q+chain.minted[i]>chain.caps[i])throw Error(t("Quantity exceeds the mint limit.","数量超过铸造上限。"));const base=chain.price*q;const gasPrice=BigInt(await provider.request({method:'eth_gasPrice'}));let fee=gasPrice*100000n;for(let j=0;j<2;j++){const gas=BigInt(await provider.request({method:'eth_estimateGas',params:[{from:sender,to:config.deskAddress,data:buyData(i,q,fee),value:hex(base+fee)}]}));fee=gas*gasPrice;}const accounts=await provider.request({method:'eth_accounts'});if(accounts[0]?.toLowerCase()!==sender.toLowerCase()||Number(await provider.request({method:'eth_chainId'}))!==config.chainId)throw Error(t("Wallet account or network changed. Please retry.","钱包账户或网络已更改，请重试。"));const hash=await provider.request({method:'eth_sendTransaction',params:[{from:sender,to:config.deskAddress,value:hex(base+fee),data:buyData(i,q,fee)}]});lastTx={hash,status:'pending'};poll(hash);}catch(e){error(e);}finally{busy=false;render();}}
async function waitReceipt(hash){for(let i=0;i<40;i++){const r=await rpc('eth_getTransactionReceipt',[hash]);if(r)return r;if(i<39)await new Promise(x=>setTimeout(x,1500));}throw Error(t("Confirmation is taking longer than expected. Check the transaction before retrying.","确认时间较长，请先查看交易状态，再决定是否重试。"));}
async function poll(hash){for(let i=0;i<40;i++){try{const receipt=await rpc('eth_getTransactionReceipt',[hash]);if(receipt){lastTx={hash,status:Number(receipt.status)===1?'confirmed':'failed'};await refresh();return;}}catch{}await new Promise(r=>setTimeout(r,3000));}}
function dataPage(){app.innerHTML=intro('Protocol data','协议数据','Supply caps and contract references by project.','项目供应上限与合约地址。')+'<div class="guide">'+['openbook','fillout'].map(k=>{const c=projectConfigs[k];return '<article><h2>'+projectName(k)+'</h2><p>'+(k==='openbook'?'Quote 78,261 · Settle 21,739 · '+t('Total','总量')+' 100,000':'Quote 31,304 · Settle 8,696 · '+t('Total','总量')+' 40,000')+'</p>'+[[t('Parts','组件'),'partsAddress'],[t('Mint desk','铸造合约'),'deskAddress'],[t('Market','市场'),'marketAddress'],[t('Circuits','电路'),'circuitsAddress']].map(([label,key])=>'<p>'+label+'<br><a class="address" href="'+c.explorerUrl+'/address/'+c[key]+'" target="_blank" rel="noopener">'+c[key]+'</a></p>').join('')+'</article>';}).join('')+'</div>';}

function whitepaper(){const sections=[[t("Projects and supply","项目与供应量"),t("OpenBook and FillOut are separate ERC-1155 collections on Robinhood Chain Mainnet. OpenBook: 78,261 Quote and 21,739 Settle. FillOut: 31,304 Quote and 8,696 Settle. The ratio is approximately 3.6:1; caps are lifetime mint limits.","OpenBook 和 FillOut 是 Robinhood Chain 主网上两个独立的 ERC-1155 系列。OpenBook：78,261 个 Quote 和 21,739 个 Settle。FillOut：31,304 个 Quote 和 8,696 个 Settle。比例约为 3.6:1；这些上限指累计铸造上限。")],[t("Studio","工作室"),t("Choose OpenBook or FillOut before creating a circuit NFT. Quote is a NAND gate; Settle stores one bit. Step advances memory once. Reset simulation clears inputs and memory while keeping your design. Drafts are saved in this browser; export a backup.","创建电路 NFT 前，请选择 OpenBook 或 FillOut。Quote 是与非门；Settle 存储一位状态。运行一步会更新一次存储状态。重置模拟会将输入和存储状态归零，同时保留电路设计。草稿保存在此浏览器中，请导出备份。")],[t("Circuit NFTs","电路 NFT"),t("Creating a circuit NFT permanently locks the required parts from the selected collection in its circuit contract. Parts cannot be recovered. Simulation runs locally in Studio; it does not automatically advance on blockchain blocks.","创建电路 NFT 会将所选系列中所需数量的组件永久锁定在对应电路合约中，无法取回。模拟在工作室本地运行，不会随区块自动推进。")],[t("Minting and trading","铸造与交易"),t("The configured mint unit price is 0.0002 ETH. Minting adds an estimated network-equivalent platform fee; wallet network fees are separate. Market purchases use existing sell listings. Both projects have separate market contracts.","当前配置的铸造单价为 0.0002 ETH。铸造时另收与预估网络费等额的平台费用；钱包网络费单独收取。市场购买通过现有卖单进行。两个项目使用独立的市场合约。")],[t("Project status","项目状态"),t("Official identifies this project’s collections and does not imply Robinhood endorsement. Deployment alone is not an independent security audit.","“官方”表示本项目发行的系列，不代表 Robinhood 的认可。合约已部署不等同于通过独立安全审计。")]];app.innerHTML=intro('Whitepaper','白皮书','Current project behavior.','当前项目说明。')+'<div class="guide">'+sections.map(([h,p])=>'<article><h2>'+h+'</h2><p>'+p+'</p></article>').join('')+'</div>';}
let ethUsd=null,ethUsdAt=0;
function listingKey(id){return 'listing-'+config.chainId+'-'+config.marketAddress.toLowerCase()+'-'+id;}
function usdMarkup(eth){return '<small class="listing-usd" data-eth-usd="'+eth+'">'+(ethUsd?'≈ '+new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:4}).format(Number(eth)*ethUsd):t('USD rate unavailable','美元汇率暂不可用'))+'</small>';}
async function updateEthUsd(){try{const r=await fetch('https://api.coinbase.com/v2/prices/ETH-USD/spot',{cache:'no-store',signal:AbortSignal.timeout(8000)});if(!r.ok)throw Error('rate');const j=await r.json();const rate=Number(j.data?.amount);if(!(rate>0))throw Error('rate');ethUsd=rate;ethUsdAt=Date.now();}catch{if(Date.now()-ethUsdAt>120000)ethUsd=null;}document.querySelectorAll('[data-eth-usd]').forEach(el=>{el.textContent=ethUsd?'≈ '+new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:4}).format(Number(el.dataset.ethUsd)*ethUsd):t('USD rate unavailable','美元汇率暂不可用');});}
setInterval(()=>{if($('#listing-box'))updateEthUsd();},60000);
function listingMarkup(id){const rows=JSON.parse(localStorage.getItem(listingKey(id))||'[]');return rows.length?'<div class="listing-grid">'+rows.map(x=>{const pending=x.listingId==='pending',valid=/^\d+$/.test(x.listingId||'')&&/^\d+$/.test(x.priceWei||'');const unit=x.priceWei?fmt(BigInt(x.priceWei)):x.price;const total=x.priceWei?fmt(BigInt(x.priceWei)*BigInt(x.amount)):String(Number(unit)*Number(x.amount));return '<article class="listing-card"><div class="listing-art"><svg viewBox="0 0 240 150" role="img" aria-label="'+names[id]+' circuit"><path d="M30 55H80 M30 95H80 M158 75H210"/><rect x="80" y="30" width="78" height="90"/><path class="chip-accent" d="M83 32V118"/><text x="119" y="80" text-anchor="middle">'+names[id]+'</text><text x="30" y="45">A</text><text x="30" y="116">B</text><text x="205" y="65">Q</text></svg></div><div class="listing-content"><div class="listing-title"><strong>'+projectName(currentProject())+'</strong><span>'+names[id]+'</span></div><p class="listing-id">'+t('Listing','挂单')+' '+(pending?t('pending','待确认'):'#'+esc(x.listingId))+'</p><div class="listing-price"><strong>'+esc(unit)+' ETH</strong><span> / '+t('unit','单位')+'</span>'+usdMarkup(unit)+'</div><dl class="listing-details"><div><dt>'+t('Quantity remaining','剩余数量')+'</dt><dd>'+esc(x.amount)+' '+names[id]+'</dd></div><div><dt>'+t('Seller','卖家')+'</dt><dd><a href="'+config.explorerUrl+'/address/'+esc(x.seller)+'" target="_blank" rel="noopener" title="'+esc(x.seller)+'">'+short(x.seller)+'</a></dd></div><div><dt>'+t('Status','状态')+'</dt><dd class="listing-state">'+(pending?t('PENDING','待确认'):t('ACTIVE','有效'))+'</dd></div><div><dt>'+t('Buy all · total','全部购买 · 总计')+'</dt><dd>'+esc(total)+' ETH'+usdMarkup(total)+'</dd></div></dl><p class="listing-gas">'+t('Network fee charged separately','网络费另计')+'</p><button class="primary listing-buy" '+(!valid||pending?'disabled':'')+' data-buy-listing="'+esc(x.listingId||'pending')+'" data-buy-amount="'+esc(x.amount)+'" data-buy-price="'+esc(x.priceWei||'')+'">'+t('Buy','购买')+'</button></div></article>';}).join('')+'</div><p class="listing-rate-note">'+t('USD estimate uses the live ETH/USD spot rate from Coinbase, refreshed every minute. ','美元估值使用 Coinbase 实时 ETH/USD 汇率，每分钟刷新。')+'</p>':'<div class="market-empty">'+t('No active listings yet.','暂无有效挂单。')+'</div>';}
const buyingListings=new Set();
function syncBuyButtons(){document.querySelectorAll('[data-buy-listing]').forEach(b=>{if(buyingListings.has(b.dataset.buyListing)){b.disabled=true;b.textContent=t('Confirming…','确认中…');}});}
async function buyListing(id,listingId,amount,priceWei){const config=projectConfigs[currentProject()];if(buyingListings.has(listingId))return;buyingListings.add(listingId);syncBuyButtons();try{if(listingId==='pending')return toast('Listing is still confirming on-chain.','挂单仍在链上确认中。');if(!account)await connect();await ensureNetwork();const current=await rpc('eth_call',[{to:config.marketAddress,data:'0xde74e57b'+word(listingId)},'latest']);const w=current.slice(2).match(/.{64}/g);if(!w||w.length<5)throw Error(t("Unable to verify listing.","无法验证挂单。"));if(BigInt('0x'+w[4])===0n||BigInt('0x'+w[2])<BigInt(amount)||BigInt('0x'+w[3])!==BigInt(priceWei)){toast('Listing changed or sold. The market has been refreshed.','挂单已变更或售出，市场已刷新。');return;}const total=BigInt(priceWei)*BigInt(amount);const hash=await provider.request({method:'eth_sendTransaction',params:[{from:account,to:config.marketAddress,data:'0xd6febde8'+word(listingId)+word(amount),value:hex(total),gas:'0x36ee8',gasPrice:await provider.request({method:'eth_gasPrice'})}]});toast('Purchase submitted. Waiting for confirmation…','购买已提交，等待确认…');const receipt=await waitReceipt(hash);if(Number(receipt.status)!==1)throw Error(t("Purchase reverted. The listing may have changed.","购买已回滚，挂单可能已变更。"));toast('Purchase confirmed.','购买已确认。');}catch(e){error(e);}finally{buyingListings.delete(listingId);await loadChainListings(id);}}
function refreshVisibleListings(){if(document.hidden)return;const match=route().match(/^market-(openbook|fillout)(?:-([01]))?$/);if(match&&$('#listing-box'))loadChainListings(Number(match[2]||0));}
setInterval(refreshVisibleListings,10000);window.addEventListener('focus',refreshVisibleListings);
let listingReadVersion=0;
async function marketRead(method,params){const response=await fetch(config.rpcUrl,{method:'POST',cache:'no-store',headers:{'Content-Type':'application/json'},body:JSON.stringify({jsonrpc:'2.0',id:Date.now(),method,params}),signal:AbortSignal.timeout(12000)});if(!response.ok)throw Error('Market network unavailable');const json=await response.json();if(json.error)throw Error(json.error.message||'Market read failed');return json.result;}
async function loadChainListings(id){const config=projectConfigs[currentProject()];const cacheKey=listingKey(id);const version=++listingReadVersion;const box=$('#listing-box');try{const block=await marketRead('eth_blockNumber',[]);const count=Number(BigInt(await marketRead('eth_call',[{to:config.marketAddress,data:'0xaaccf1ec'},block])));const rows=[];for(let offset=0;offset<count;offset+=20){const batch=await Promise.all(Array.from({length:Math.min(20,count-offset)},async(_,j)=>{const listingId=offset+j;const data=await marketRead('eth_call',[{to:config.marketAddress,data:'0xde74e57b'+word(listingId)},block]);const w=data.slice(2).match(/.{64}/g);if(!w||w.length<5)throw Error('Invalid listing response');if(BigInt('0x'+w[1])!==BigInt(id)||BigInt('0x'+w[2])===0n||BigInt('0x'+w[4])===0n)return null;return {listingId:String(listingId),seller:'0x'+w[0].slice(-40),amount:String(BigInt('0x'+w[2])),priceWei:String(BigInt('0x'+w[3])),price:fmt(BigInt('0x'+w[3]))};}));rows.push(...batch.filter(Boolean));}if(version!==listingReadVersion)return;localStorage.setItem(cacheKey,JSON.stringify(rows));if(box?.isConnected)box.innerHTML=listingMarkup(id);syncBuyButtons();updateEthUsd();}catch(e){if(version!==listingReadVersion)return;if(box?.isConnected)box.innerHTML='<div class="market-empty">'+t('Unable to load current listings. Please refresh.','无法加载最新挂单，请刷新。')+'</div>';}}
function marketDetail(routeKey){const config=projectConfigs[routeKey.split('-')[0]];const parts=routeKey.split('-'),project=parts[0],id=parts[1]==='1'?1:0,title=project==='openbook'?'OpenBook':'FillOut',live=!!config.marketAddress;app.innerHTML=intro(title,title,'Peer-to-peer market · '+names[id],'点对点市场 · '+names[id])+'<div class="trade-tabs"><button class="trade-tab active" data-trade="buy">'+t("Buy","购买")+'</button><button class="trade-tab" data-trade="sell">'+t("Sell","出售")+'</button></div><section class="market-card trade-pane" data-pane="buy"><h2>'+t("Buy","购买")+' '+names[id]+'</h2><p class="muted">'+t("Enter your price and quantity. Active listings will appear below.","有效挂单显示在下方。")+'</p><div class="market-empty">'+t("No active listings yet.","暂无有效挂单。")+'</div></section><section class="market-card trade-pane" data-pane="sell" hidden><h2>'+t("Sell","出售")+' '+names[id]+'</h2><p class="muted">'+(live?t("Approve your token, then list it at your price.","先授权代币，再按你的价格挂单。"):t("FillOut contracts are not deployed yet.","FillOut 合约尚未部署。"))+'</p><div class="market-form"><label>'+t("Price per unit (ETH)","单价（ETH）")+'<input id="sell-price" placeholder="0.0003" '+(live?'':'disabled')+'></label><label>'+t("Quantity","数量")+'<input id="sell-amount" type="number" min="1" value="1" '+(live?'':'disabled')+'></label></div><button id="sell-submit" class="primary" '+(live?'':'disabled')+'>'+t("Approve and list","授权并挂单")+'</button><p id="market-status" class="small-note"></p></section><section class="market-card"><h2>'+t("Listings","挂单")+'</h2><div id="listing-box"></div></section>';const initialListingBox=$('#listing-box');if(initialListingBox){initialListingBox.innerHTML='<div class="market-empty">'+t('Loading listings…','正在加载挂单…')+'</div>';initialListingBox.onclick=e=>{const b=e.target.closest('[data-buy-listing]');if(b)buyListing(id,b.dataset.buyListing,b.dataset.buyAmount,b.dataset.buyPrice);};}if(live)loadChainListings(id);document.querySelectorAll('.trade-tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.trade-tab').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.trade-pane').forEach(x=>x.hidden=x.dataset.pane!==b.dataset.trade);});document.querySelector('#sell-submit')?.addEventListener('click',async()=>{try{if(!account)await connect();await ensureNetwork();const txt=$('#sell-price').value.trim()||'0';const [whole,frac='']=txt.split('.');const price=BigInt(whole||0)*1000000000000000000n+BigInt((frac+'000000000000000000').slice(0,18));const amount=BigInt(Math.max(1,Number($('#sell-amount').value)||1));if(!balances||balances[id]<amount){toast('Insufficient token balance for this listing.','此挂单数量超过代币余额。');return;}if(price<=0n)throw Error(t("Enter a valid price.","请输入有效价格。"));const pad=n=>n.toString(16).padStart(64,'0');const op=config.marketAddress.slice(2).toLowerCase().padStart(64,'0')+'1'.padStart(64,'0');$('#market-status').textContent=t('Confirm token approval in your wallet…','请在钱包中确认代币授权…');const approvalHash=await provider.request({method:'eth_sendTransaction',params:[{from:account,to:config.partsAddress,data:'0xa22cb465'+op,gas:'0x186a0',gasPrice:await provider.request({method:'eth_gasPrice'})} ]});const approvalReceipt=await waitReceipt(approvalHash);if(Number(approvalReceipt.status)!==1)throw Error(t("Token approval failed.","代币授权失败。"));$('#market-status').textContent=t('Confirm listing in your wallet…','请在钱包中确认挂单…');const listingHash=await provider.request({method:'eth_sendTransaction',params:[{from:account,to:config.marketAddress,data:'0xb03053b6'+pad(id)+pad(amount)+pad(price),gas:'0x36ee8',gasPrice:await provider.request({method:'eth_gasPrice'})}]});const rows=JSON.parse(localStorage.getItem(listingKey(id))||'[]');rows.unshift({amount:String(amount),price:txt,priceWei:price.toString(),listingId:'pending',seller:account,hash:listingHash});localStorage.setItem(listingKey(id),JSON.stringify(rows));const box=$('#listing-box');if(box)box.innerHTML=listingMarkup(id);$('#market-status').textContent=t('Listing submitted.','挂单已提交。');}catch(e){error(e);}});}
let fillingCircuit=false;
async function createCircuit(binary,quotes,settles,project){const config=projectConfigs[project];if(!config)throw Error(t("Choose a project first.","请先选择项目。"));if(fillingCircuit)return;fillingCircuit=true;const lock=()=>{const b=$('#create-circuit');if(b){b.disabled=true;b.textContent=t('Waiting for wallet…','等待钱包…');}};lock();try{if(!account)await connect();await ensureNetwork();lock();const sender=account;for(const [id,needed] of [[0,quotes],[1,settles]]){const balance=BigInt(await rpc('eth_call',[{to:config.partsAddress,data:'0x00fdd58e'+sender.slice(2).padStart(64,'0')+word(id)},'latest']));if(balance<BigInt(needed))throw Error(t('Insufficient ','余额不足：')+names[id]+t(': need ','，需要 ')+needed);}
const op=config.circuitsAddress.slice(2).padStart(64,'0');const approved=BigInt(await rpc('eth_call',[{to:config.partsAddress,data:'0xe985e9c5'+sender.slice(2).padStart(64,'0')+op},'latest']));
async function send(to,data){if((await provider.request({method:'eth_accounts'}))[0]?.toLowerCase()!==sender.toLowerCase())throw Error(t("Wallet account changed.","钱包账户已更改。"));await ensureNetwork();const tx={from:sender,to,data,value:'0x0'};const estimate=BigInt(await provider.request({method:'eth_estimateGas',params:[tx]}));tx.gas=hex(estimate*120n/100n);tx.gasPrice=await provider.request({method:'eth_gasPrice'});return provider.request({method:'eth_sendTransaction',params:[tx]});}
if(!approved){toast('Approve parts access for the circuit contract.','请授权电路合约使用组件。');const approval=await send(config.partsAddress,'0xa22cb465'+op+word(1));if(Number((await waitReceipt(approval)).status)!==1)throw Error(t("Approval failed.","授权失败。"));}
const bytes=binary.slice(2);const data='0xaf0a675b'+word(32)+word(bytes.length/2)+bytes.padEnd(Math.ceil(bytes.length/64)*64,'0');const hash=await send(config.circuitsAddress,data);toast('Circuit submitted. Waiting for confirmation…','电路已提交，等待确认…');const receipt=await waitReceipt(hash);if(Number(receipt.status)!==1)throw Error(t("Circuit creation reverted.","电路创建已回滚。"));toast('Circuit NFT created. Parts permanently locked.','电路 NFT 已创建，组件已永久锁定。');await refresh();const status=$('#studio-error');if(status)status.innerHTML='<a target="_blank" rel="noopener" href="'+config.explorerUrl+'/tx/'+hash+'">'+t('Circuit confirmed · View transaction','电路已确认 · 查看交易')+'</a>'; }catch(e){error(e);}finally{fillingCircuit=false;const b=$('#create-circuit');if(b){b.disabled=false;b.textContent=t('Create circuit NFT','创建电路 NFT');}}}
function render(){if(!config)return;const k=currentProject();if(projectConfigs&&config.partsAddress!==projectConfigs[k].partsAddress){config={...projectConfigs[k]};readId++;chain=null;balances=null;queueMicrotask(refresh);}header();const r=route();if(r==='studio')mountStudio(app,createCircuit);else if(/^market-(openbook|fillout)-[01]$/.test(r))marketDetail(r.replace('market-',''));else if(r==='market-openbook'||r==='market-fillout')marketDetail(r.replace('market-','')+'-0');else if(/^(fillout|openbook)-[01]$/.test(r))mintPage(Number(r.at(-1)),r.split('-')[0]);else if(/^mint-[01]$/.test(r))mintPage(Number(r.at(-1)));else if(r==='foundry')mintPage(0);else ({projects,market,data:dataPage,wallet:holdings,airdrop:holdings,whitepaper,guide:whitepaper}[r]||projects)();if(loadError&&r!=='studio'){const p=document.createElement('p');p.className='alert';p.textContent=t('Live data unavailable. Reconnect to Robinhood Chain Mainnet and refresh.','实时数据暂不可用。请重新连接 Robinhood Chain 主网并刷新。');app.prepend(p);}}
window.addEventListener('hashchange',render);
try{config=await fetch('config.json',{cache:'no-store'}).then(r=>r.json());projectConfigs={openbook:Object.freeze({...config}),fillout:Object.freeze({...config,...config.fillout})};render();if(window.ethereum){useProvider();account=(await provider.request({method:'eth_accounts'}))[0]||null;}await refresh();}catch(e){app.textContent=t('Unable to load the app. Please reload.','无法加载应用，请刷新页面。');}



